  const config={...E.startProfile('male'),race:'human',face:'strong-jaw',hair:'waves',eyes:'keen',nose:'broad',beard:'none',headwear:'none',age:'young',marks:'none',clothing:'steel-cuirass'},base=A.build(config),before=Object.fromEntries(E.order.map(s=>[s.id,signature(base.layers[s.id])])),same=A.build(config);
